import hashlib,json,pathlib
P=pathlib.Path(__file__).parent
ROOT=P.parent
def cb(x):return json.dumps(x,sort_keys=True,separators=(',',':'),ensure_ascii=False,allow_nan=False).encode()
def read(p):return json.loads(pathlib.Path(p).read_text())
def pin(p):return {'PATH':str(p),'RAW_SHA256':hashlib.sha256(pathlib.Path(p).read_bytes()).hexdigest()}
def write(n,x):
    if (P/n).exists():
        assert read(P/n)==x, 'DOCUMENTARY_CONTENT_CONFLICT:'+n
        return
    with (P/n).open('x') as f:f.write(json.dumps(x,sort_keys=True,indent=2)+'\n')
def aid(x,ns):return {'kind':'CONTENT_IDENTITY','namespace':ns,'sha256':hashlib.sha256(cb(x)).hexdigest()}
